import{z as A,x as p,o as r,c as B,q as l,j as o,D as e,d as t,s as E,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"半虚拟化","description":"","frontmatter":{"title":"半虚拟化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/paravirtualization.md","filePath":"cs/paravirtualization.md","lastUpdated":1791413859000}'),d={name:"cs/paravirtualization.md"};function h(v,a,u,c,m,f){const s=p("Mermaid");return r(),B("div",null,[a[2]||(a[2]=l('<h1 id="半虚拟化" tabindex="-1">半虚拟化 <a class="header-anchor" href="#半虚拟化" aria-label="Permalink to &quot;半虚拟化&quot;">​</a></h1><div class="epigraph"><p>半虚拟化让客户知道自己在 VM 里：用 hypercall 或 virtio 环替代模拟遗留设备，从而少 VM-exit、少模拟税。</p><footer>—— 据 Barham et al., Xen；Russell, virtio；[KVM/QEMU](/cs/kvm-qemu) 为先修</footer></div><p><a href="/cs/shadow-page-table">EPT</a> 解决 MMU。<a href="/cs/vmx-vmexit">VM-exit</a> 仍会被模拟网卡打爆。缺口是 <strong>virtio/xen PV</strong>：客户驱动配合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模拟 e1000：每发包 PIO/MMIO exit。virtio：共享环、kick 可用 eventfd，批量。缺口：virtio-net/blk/fs；与 <a href="/cs/sendfile-splice">sendfile</a> 在客户内仍有效。本课不把 virtio 规范全章抄来。</p><p><span class="marginnote">「模拟税」指客户每碰一次模拟设备就触发一次 VM-exit：CPU 要把完整状态存进 VMCS、跳进宿主模拟代码再恢复回来，单次约 1–2 微秒。10 Gbps 线速下每秒上千万个包，CPU 全耗在进出上，包反而发不动。</span></p><p><span class="marginnote">启蒙（enlightenment）是 Windows 用语。对象是知情客户，不是类型 1 专属。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户装 virtio 驱动 → 发现 PCI virtio 设备 → 环与 QEMU/vhost 通信。vhost：部分数据面进宿主内核，少到用户。对照 <a href="/cs/bridge-tun-tap">tun</a>：tap 仍常是后端。对照 XDP：宿主可对 tap 再加速。</p>',9)),(r(),o(n,null,{default:e(()=>[E(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20GDRV%5B%22%E5%AE%A2%E6%88%B7%20virtio%20%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20RING%5B%22%E5%85%B1%E4%BA%AB%E7%8E%AF%22%5D%0A%20%20RING%20--%3E%20VHOST%5B%22vhost%20%E6%88%96%20QEMU%22%5D%0A%20%20VHOST%20--%3E%20TAP%5B%22tap%2F%E6%96%87%E4%BB%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,[t("半虚拟把设备模型从「精确模拟硬件」换成「为 VM 设计的 ABI」，性能接近直通的一部分，可迁移性更好。不要写成云网卡型号。与 "),i("a",{href:"/cs/scsi-stack"},"SCSI"),t("：virtio-blk 绕过客户 SCSI 模拟。")],-1)),a[5]||(a[5]=i("p",null,"无 PV 驱动则掉进慢模拟。",-1)),a[6]||(a[6]=i("p",null,[i("span",{class:"marginnote"},"共享环可以想象成两家公司共用的一条传送带：客户机把包裹（缓冲区描述符）放上去，宿主取走处理，双方各自记账、不必每次都「敲门」（VM-exit）。kick 只是偶尔喊一嗓子「有货了」。")],-1)),(r(),o(n,null,{default:e(()=>[E(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20OLD%5B%22%E6%A8%A1%E6%8B%9F%20e1000%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20A1%5B%22%E5%AE%A2%E6%88%B7%E5%8F%91%E5%8C%85%22%5D%20--%3E%20A2%5B%22%E5%86%99%E6%A8%A1%E6%8B%9F%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22VM-exit%20%E6%AF%8F%E5%8C%85%E4%B8%80%E6%AC%A1%22%5D%0A%20%20%20%20A3%20--%3E%20A4%5B%22%E5%AE%BF%E4%B8%BB%E9%80%90%E5%8C%85%E6%A8%A1%E6%8B%9F%22%5D%0A%20%20end%0A%20%20subgraph%20NEW%5B%22virtio%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20B1%5B%22%E5%AE%A2%E6%88%B7%E6%89%B9%E9%87%8F%E6%94%BE%E6%8F%8F%E8%BF%B0%E7%AC%A6%E8%BF%9B%E7%8E%AF%22%5D%20--%3E%20B2%5B%22kick%20%E4%B8%80%E6%AC%A1%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E5%AE%BF%E4%B8%BB%E6%89%B9%E9%87%8F%E6%B6%88%E8%B4%B9%E7%8E%AF%22%5D%0A%20%20end%0A%20%20OLD%20-.%20%22%E5%B0%91%E4%B8%A4%E4%B8%AA%E6%95%B0%E9%87%8F%E7%BA%A7%20exit%22%20.-%3E%20NEW%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>常见误区：把 virtio 当成某块真实网卡的型号。它其实是「为 VM 专门设计的设备接口约定」，客户装的是 virtio 驱动、看见的是一块虚拟 PCI 设备——正因如此它没有历史包袱，才能把协议做成批量、共享内存式的。</p><p>实现上：vhost-net 在宿主内核消费 virtio 环，QEMU 只处理控制面。无 PV 驱动时海量 exit 模拟 e1000。virtio-fs 用 FUSE 协议过环，语义接近本地但不是。 读法上只引用<a href="/cs/shadow-page-table">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>半虚拟化</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 virtio 特性位。不保证 GPU 半虚拟的完整。下一课硬件级：SR-IOV 与直通。</p><p>版本字段会变，课序钉的是机制对象「半虚拟化」，不是某一主线内核的结构体名。 后课默认：知情客户可用环 I/O。把物理函数切成虚拟函数，下一课 SR-IOV。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半虚拟用 hypercall/virtio 减少模拟。</li><li>vhost 把数据面放进宿主内核。</li><li>SR-IOV 直通是下一课。</li><li>出处：Xen；virtio；KVM vhost。</li></ul>',9))])}const D=A(d,[["render",h]]);export{P as __pageData,D as default};
